(function(T){
  'use strict';
  const $=s=>document.querySelector(s),all=s=>Array.from(document.querySelectorAll(s)),E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),I=T.icon;
  const B=(label,action,cls='secondary',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
  const date=v=>v?new Intl.DateTimeFormat('ms-MY',{dateStyle:'long',timeZone:'Asia/Kuala_Lumpur'}).format(new Date(v)):'—';
  let db,storageOK=true,storageWarning='',view='home',qId=1,mode='mouse',answer={},selected=null,feedback=null,modal=null,returnFocus=null,scene=null,lastTime=null,trackingHold=false,practiceSession=null,reviewSession=null,reviewHint=0,controlReturn='map',scanIndex=0,detectiveIndex=0,detectiveFeedback='',training={step:0,targets:[],selected:false,placed:false},chestKeys=[],chestSelected=null,chestOpen=false,teacherId=null,selectedRecords=new Set(),toastTimer;
  try{db=T.readDatabase(localStorage.getItem(T.STORAGE_KEY));}catch{db=T.newDatabase();storageOK=false;storageWarning='Rekod tidak dapat dibaca. Data lama tidak ditindih. Gunakan pelayar yang membenarkan storan atau eksport rekod yang masih boleh dibuka.';}
  const original=()=>db.sessions.find(s=>s.sessionId===db.activeId),S=()=>reviewSession||practiceSession||original(),Q=()=>T.questions[qId-1],isReview=()=>!!reviewSession;
  const hub=new T.InputHub({onActivate:activate,onDrop:drop,onMove:trainingMove,onMotor:message=>toast(message),onHold:()=>sound('hold')});
  const tracker=new T.HandTracker({settings:()=>db.settings,onPoint:p=>{trackingHold=false;if(mode==='hand')hub.hand(p,db.settings);updateTracking();},onCancel:()=>{if(mode==='hand'){flush();lastTime=null;trackingHold=true;}hub.hide();},onLost:()=>{if(mode==='hand'&&view==='question'&&!S()?.pausedState){if(!isReview()&&!practiceSession){S().motorHelp++;S().trackingLosses++;}pause('Tangan belum dikesan. Tunjukkan tangan semula, kemudian pilih Sambung.');}},onStatus:updateTracking});
  function save(){if(!storageOK)return;try{localStorage.setItem(T.STORAGE_KEY,JSON.stringify(db));}catch{storageOK=false;storageWarning='Kemajuan baharu belum disimpan kerana storan penuh atau disekat. Cetak atau eksport rekod sebelum menutup halaman.';toast(storageWarning);}}
  function toast(message){clearTimeout(toastTimer);$('#notice').textContent=message;$('#notice').hidden=false;toastTimer=setTimeout(()=>$('#notice').hidden=true,5500);}
  function settings(){const s=db.settings;for(const [key,cls]of[['largeText','large-text'],['contrast','high-contrast'],['calm','reduced-motion'],['simple','simple-mode']])document.body.classList.toggle(cls,!!s[key]);tracker.showPreview(s.preview&&mode==='hand');}
  function go(next){flush();lastTime=null;hub.cancel();hub.dwell.reset();stopSpeech();view=next;selected=null;render();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});}
  function render(){scene?.dispose();scene=null;settings();const screens={home:Home,scan:Scan,detective:Detective,register:Registration,controls:Controls,training:Training,map:MapScreen,intro:Intro,question:Question,level:Level,chest:Chest,summary:Summary,teacher:Teacher,guide:Guide,cards:PrintCards};$('#app').innerHTML=Header()+`<main id="main" tabindex="-1" class="main ${view}-view">${storageWarning?`<div class="warning" role="alert">${E(storageWarning)}</div>`:''}${screens[view]()}</main>`+Footer();renderModal();if($('#room-canvas'))scene=new T.RoomScene($('#room-canvas'),{door:Q().door,q:Q(),completed:T.stats(S(),Q().door).completed,success:!!feedback?.correct,calm:db.settings.calm,simple:db.settings.simple});updateTracking();updateClock();lastTime=canTime()?performance.now():null;}
  function Header(){return `<header class="topbar"><div class="header-inner"><button class="brand" data-action="home" aria-label="TIBA+ meN-, menu utama"><span class="brand-mark">${I('key')}</span><span>TIBA<span class="brand-plus">+</span> <b>meN-</b><small>MISI SELAMATKAN BAHASA</small></span></button><nav aria-label="Menu utama"><span class="subject-tag">BAHASA MELAYU · TAHUN 2</span>${B(I('teacher')+'<span>Panduan guru</span>','teacher-gate','nav-btn','aria-label="Panduan dan rekod guru"')}${B(I('settings')+'<span>Tetapan</span>','settings','nav-btn','aria-label="Tetapan aksesibiliti"')}${B(I('expand')+'<span>Skrin penuh</span>','fullscreen','nav-btn','aria-label="Skrin penuh"')}</nav></div></header>`;}
  function Footer(){return `<footer class="footer"><span>${I('shield')} Belajar ikut rentak sendiri. Tiada had masa.</span><span>TIBA+ meN- · Istana Kata</span></footer>`;}
  function Home(){return `<section class="new-hero"><div><span class="eyebrow">OPERASI ENAM KUNCI AJAIB</span><h1>Misi selamatkan<br><em>bahasa!</em></h1><p class="hero-lead">Istana Kata memerlukan kamu.</p><p>Mesin imbuhan terhenti, robot keliru dan portal bahasa tertutup. Bantu MIM mencari enam kunci dan memulihkan dunia kata!</p><div class="hero-actions">${B('Mulakan escape room '+I('arrow'),'new-student','primary large')}${original()?B(I('refresh')+' Sambung misi','resume','secondary'):''}</div><div class="hero-tags"><span>${I('key')} 6 bilik ajaib</span><span>${I('puzzle')} 24 cabaran</span><span>${I('hand')} Tangan atau tetikus</span></div></div><div class="hero-castle">${T.castle()}<div class="hero-mim">${T.mim()}<div>Hai! Saya <b>MIM.</b><br>Jom jadi Penjaga Bahasa!</div></div><span class="castle-label">SELAMAT DATANG KE ISTANA KATA</span></div></section><section class="learning-trail"><div class="section-top"><div><span class="eyebrow">SEBELUM MEMBUKA PINTU</span><h2>Kenal dahulu. Kemudian teroka.</h2></div><p>Latihan awal tidak mengubah rekod misi.</p></div><div class="learning-cards"><button data-action="scan"><span class="learning-number">01</span>${I('eye')}<h3>Imbas & Kenal</h3><p>Lihat kata dasar, imbuhan dan perbuatan.</p><span>Kenali keluarga meN- ${I('arrow')}</span></button><button data-action="detective"><span class="learning-number">02</span>${I('bulb')}<h3>Detektif Imbuhan</h3><p>Cuba latihan pendek bersama MIM.</p><span>Berlatih tanpa markah ${I('arrow')}</span></button><button data-action="new-student"><span class="learning-number">03</span>${I('key')}<h3>Operasi Enam Kunci</h3><p>Pulihkan enam bilik dan buka peti bahasa.</p><span>Mula pengembaraan ${I('arrow')}</span></button></div></section><section class="home-rooms"><span class="eyebrow">ENAM TEMPAT UNTUK DITEROKA</span><div>${T.doors.map(d=>`<span style="--room-color:${d.color}"><i>${d.key}</i><b>${d.title}</b><small>${d.level}</small></span>`).join('')}</div></section><p class="landscape-note">${I('map')} Paparan landskap pada komputer riba atau desktop disyorkan. Tetikus, sentuhan dan papan kekunci sentiasa tersedia.</p>`;}
  function Heading(label,title,desc=''){return `<div class="page-heading"><span class="eyebrow">${label}</span><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>`;}
  function Scan(){const w=T.words[scanIndex];return `${Heading('IMBAS & KENAL','Satu keluarga, banyak bentuk.','meN- ialah lambang keluarga awalan. Huruf N tidak ditulis dalam kata yang terhasil.')}<section class="scan-card"><div class="word-picture">${T.scene(w.scene,`Ilustrasi ${w.result}`)}</div><div><span class="eyebrow">KATA ${scanIndex+1} / ${T.words.length}</span><div class="word-transform"><span>${w.drop?`<del>${w.drop}</del>${E(w.base.slice(1))}`:w.base}</span>${I('arrow')}<strong>${w.result}</strong></div><p>${w.drop?`Dalam contoh ini, huruf ${w.drop} digugurkan dan awalan ${w.prefix} digunakan.`:`Kata dasar ${w.base} menerima awalan ${w.prefix}.`}</p><div class="center-actions">${B(I('back')+' Sebelumnya','scan-prev','secondary')}${B(I('sound')+' Dengar','speak-scan','secondary')}${B('Seterusnya '+I('arrow'),'scan-next','primary')}</div></div></section><div class="word-nav">${T.words.map((w,i)=>B(w.base,'scan-word',i===scanIndex?'primary':'secondary',`data-index="${i}"`)).join('')}</div><p class="muted centered">Contoh ini menggunakan kata lazim. Pengguguran huruf bukan peraturan mutlak untuk semua kata.</p><div class="center-actions">${B('Teruskan: Detektif Imbuhan '+I('arrow'),'detective','primary')}${B('Menu utama','home','secondary')}</div>`;}
  function Detective(){const q=T.detective[detectiveIndex];return `${Heading('LATIHAN AWAL · TIDAK DIREKODKAN','Jadi detektif imbuhan!','Cuba dahulu bersama MIM. Kamu boleh mengulang latihan.')}<section class="detective-card"><div class="mim-message">${T.mim()}<p>${q.prompt}</p></div><div class="detective-options">${q.options.map((o,i)=>B(o,'detect-answer','answer',`data-index="${i}"`)).join('')}</div><p class="detective-feedback" role="status">${E(detectiveFeedback)||'Pilih satu jawapan.'}</p><div class="center-actions">${B('Ulang soalan','detect-repeat','secondary')}${B(detectiveIndex<3?'Soalan seterusnya':'Isi profil murid',detectiveIndex<3?'detect-next':'new-student','primary')}</div><span class="muted">Latihan ${detectiveIndex+1}/4 · Tiada pemasa misi</span></section>`;}
  function Registration(){return `${Heading('PASPORT PENJAGA BAHASA','Hai, pengembara!','Nama dan kelas membantu guru mengenali rekod pembelajaran kamu.')}<section class="registration-card"><div class="register-art">${T.mim()}<h2>Enam kunci menanti.<br>Kamu sedia membantu?</h2><p>Guru boleh membantu kamu menaip.</p></div><form id="registration" novalidate><label for="student-name">Nama murid</label><input id="student-name" name="studentName" maxlength="80" placeholder="Taip nama kamu" autocomplete="off" required><label for="student-class">Kelas</label><input id="student-class" name="studentClass" maxlength="40" placeholder="Contoh: 2 Bestari" autocomplete="off" required><fieldset class="avatar-picker"><legend>Pilih avatar kamu</legend>${[['robot','Robot'],['cat','Kucing'],['astronaut','Angkasawan']].map(([v,l],i)=>`<label><input type="radio" name="avatar" value="${v}" ${i===0?'checked':''}>${T.avatar(v)}<span>${l}</span></label>`).join('')}</fieldset><p id="form-error" role="alert"></p><button class="btn primary full" type="submit">Mulakan misi ${I('arrow')}</button><small>Selepas ini, pilih kawalan dan berlatih. Pemasa belum bermula.</small></form></section>`;}
  function Controls(){const ready=mode==='mouse'||tracker.ready&&tracker.detected;return `${Heading('PILIH KAWALAN','Main dengan cara kamu.','Latihan dan persediaan kamera tidak dikira dalam masa menjawab.')}<section class="control-panel"><div class="control-options">${B(I('mouse')+'<b>Main dengan tetikus</b><span>Klik, sentuh, seret atau gunakan papan kekunci.</span>','mode-mouse','mode-card '+(mode==='mouse'?'active':''))}${B(I('hand')+'<b>Main dengan gerakan tangan</b><span>Gunakan satu tangan di hadapan kamera.</span>','mode-hand','mode-card '+(mode==='hand'?'active':''))}</div>${mode==='hand'?`<div class="camera-setup"><div><h2>Sediakan tangan kamu</h2><p>Tunjukkan satu tangan dan buka cubitan dahulu. Kamera hanya aktif selepas kamu menekan butang di bawah.</p><p class="tracking-status" data-tracking-status role="status">${E(tracker.message||'Kamera dimatikan')}</p><div class="center-actions">${B(I('camera')+' Aktifkan kamera','camera-on','primary',tracker.state==='loading'?'disabled':'')}${B('Matikan kamera','camera-off','secondary')}${B('Sembunyi / tunjuk pratonton','camera-preview','text-btn')}</div></div><div class="camera-privacy">${I('shield')} Bingkai kamera diproses pada peranti. Video tidak dirakam atau dihantar ke pelayan.</div></div>`:'<p class="control-note">Tetikus tersedia serta-merta. Kamera dan model tidak dimuatkan dalam mod ini.</p>'}<div class="control-config"><label>Cara memilih<select id="activation-setting"><option value="pinch" ${db.settings.activation==='pinch'?'selected':''}>Cubitan tangan / klik</option><option value="dwell" ${db.settings.activation==='dwell'?'selected':''}>Tahan untuk pilih</option></select></label><label>Tangan pilihan<select id="hand-setting"><option value="either" ${db.settings.hand==='either'?'selected':''}>Mana-mana tangan</option><option value="left" ${db.settings.hand==='left'?'selected':''}>Tangan kiri</option><option value="right" ${db.settings.hand==='right'?'selected':''}>Tangan kanan</option></select></label><label>Tempoh tahan (saat)<input id="dwell-setting" type="number" min="0.6" max="3" step="0.1" value="${db.settings.dwellMs/1000}"></label><label>Kawasan gerakan <span id="range-label">${Math.round(db.settings.range*100)}%</span><input id="range-setting" type="range" min="45" max="100" step="5" value="${db.settings.range*100}"></label></div><p class="muted">Kalibrasi: pilih kawasan lebih kecil jika sukar mencapai tepi skrin. Gunakan Latihan kawalan untuk mencuba tiga sasaran. Gerakkan tangan ke arah yang sama seperti penunjuk bercahaya.</p><div class="center-actions">${B('Latihan kawalan '+I('arrow'),'train','primary','id="training-start" '+(!ready?'disabled':''))}${B('Kembali','control-back','secondary')}</div></section>`;}
  function Training(){const step=training.step;return `${Heading('LATIHAN KAWALAN · TIADA MARKAH','Cuba bersama MIM.','Kawalan sama digunakan di semua bilik. Kamu tidak perlu bergerak pantas.')}<section class="training-panel"><div class="mim-message">${T.mim()}<p>${['Gerakkan penunjuk ke tiga sasaran besar. Kamu juga boleh memilih sasaran.','Pilih kunci ini: klik, cubit dan buka, atau tahan sehingga gelang penuh.','Pindahkan kad ke ruang. Atau pilih kad dahulu, kemudian pilih ruang.','Hebat! Kamu sudah bersedia untuk pengembaraan.'][step]}</p></div><div class="control-demo" aria-hidden="true"><span>${I('hand')}</span><span>${I('arrow')}</span><span>${I('puzzle')}</span><span>${I('arrow')}</span><span>${I('check')}</span></div>${step===0?`<div class="training-targets">${[0,1,2].map(i=>B(training.targets.includes(i)?I('check'):String(i+1),'train-target','training-target '+(training.targets.includes(i)?'reached':''),`data-index="${i}" data-training-target="${i}"`)).join('')}</div>`:step===1?B(I('key')+' Pilih kunci','train-select','practice-key'):step===2?`<div class="training-transfer"><button class="game-card ${training.selected?'selected':''}" data-card data-comp="training" data-choice="0">${I('star')} Kad bintang</button>${I('arrow')}<button class="answer-slot" data-slot="training" data-comp="training">${training.placed?'Bintang diletakkan!':'Letakkan kad di sini'}</button></div>`:`<div class="training-done">${I('check')} Latihan selesai. Masa menjawab masih belum berjalan.</div>`}<div class="center-actions">${B('Ulang latihan','train-repeat','secondary')}${B(step===3?(controlReturn==='question'?'Kembali ke misi':'Lihat peta istana'):'Selesaikan latihan dahulu','training-done','primary',step!==3?'disabled':'')}${B('Tukar kawalan','controls','text-btn')}</div></section>`;}
  function MapScreen(){const s=original();if(!s)return Home();const z=T.stats(s);return `${Heading('PETA ISTANA KATA',`Selamat datang, ${E(s.studentName)}!`,`${E(s.studentClass)} · Hai! Saya MIM. Jom cari enam kunci dan buka peti bahasa!`)}<div class="progress-strip"><span>${I('key')} <b>${z.doors}/6</b> kunci</span><span>${I('check')} <b>${z.completed}/24</b> cabaran selesai</span><span>${I('clock')} <b>${T.formatTime(z.duration)}</b> masa menjawab</span></div><section class="castle-map">${T.doors.map(d=>{const n=T.stats(s,d.id).completed,done=n===4,unlocked=T.isUnlocked(s,d.id);return `<button class="room-card ${done?'done':unlocked?'current':'locked'}" style="--room-color:${d.color}" data-action="enter-room" data-door="${d.id}" ${!unlocked?'disabled':''}><span class="room-map-icon">${I(done?'key':unlocked?'spark':'lock')}<b>${done?d.key:d.id}</b></span><small>BILIK ${d.id} · ${done?'SELESAI':unlocked?'SEDIA DITEROKA':'BERKUNCI'}</small><h2>${d.title}</h2><p>${d.level}</p><span class="room-lights">${[0,1,2,3].map(i=>`<i class="${i<n?'lit':''}">${i<n?'✓':''}</i>`).join('')}</span></button>`;}).join('')}</section><div class="center-actions">${B(z.completed===24?'Buka peti bahasa':'Sambung pengembaraan','continue','primary')}${B('Lihat ringkasan','summary','secondary')}${B('Tukar kawalan','controls','secondary')}</div><p class="muted centered">Bilik selesai boleh diulang untuk latihan. Rekod asal kekal.</p>`;}
  function Intro(){const d=T.doors[Q().door-1];return `<section class="room-intro" style="--room-color:${d.color}"><span class="eyebrow">PERINGKAT ${d.id}/6</span><div class="intro-key">${I('key')}<b>${d.key}</b></div><h1>${d.title}</h1><div class="mim-message">${T.mim()}<p>${d.instruction}</p></div><p>Selesaikan empat cabaran untuk mendapatkan kunci ${d.key}.</p><div class="center-actions">${B('Masuk bilik '+I('arrow'),'start-room','primary')}${B('Kembali ke peta','map','secondary')}</div><small>Pemasa bermula apabila cabaran dipaparkan.</small></section>`;}
  function learnerStrip(s,q){return `<div class="mission-strip"><span class="learner-avatar">${T.avatar(s.avatar)}</span><span class="learner"><b>${E(s.studentName)}</b><small>${E(s.studentClass)}${isReview()?' · SEMAKAN GURU':practiceSession?' · LATIHAN ULANGAN':''}</small></span><span><small>Peringkat</small><b>${q.door}/6</b></span><span><small>Cabaran</small><b>${(q.id-1)%4+1}/4</b></span><span><small>Kunci</small><b>${T.stats(s).doors}/6</b></span><span class="timer"><small>Masa menjawab</small><b data-time="total">${T.formatTime(s.totalActiveDuration)}</b></span>${B(I('pause')+' Henti seketika','pause','secondary')}</div>`;}
  function Question(){const q=Q(),s=S(),d=T.doors[q.door-1],r=s.records[q.id],paused=s.pausedState;return `<div class="question-top">${B(I('back')+(isReview()?' Keluar semakan':' Peta istana'),isReview()?'end-review':'map','text-btn')}<span class="control-status">${I(mode==='hand'?'hand':'mouse')} ${mode==='hand'?'Gerakan tangan':'Tetikus'} <small data-tracking-status>${mode==='hand'?E(tracker.message):''}</small></span></div>${learnerStrip(s,q)}${isReview()?ReviewNav():''}<section class="room-stage" style="--room-color:${d.color}"><div class="room-title"><div><span class="eyebrow">BILIK ${q.door}</span><h2>${d.title}</h2></div><div class="room-lights" aria-label="${T.stats(s,q.door).completed} daripada 4 cabaran selesai">${[0,1,2,3].map(i=>`<i class="${s.records[(q.door-1)*4+i+1].completed?'lit':''}">${s.records[(q.door-1)*4+i+1].completed?'✓':''}</i>`).join('')}</div></div><canvas id="room-canvas" class="room-canvas" role="img" aria-label="${E(feedback?.correct?q.effect:d.title+'. '+T.stats(s,q.door).completed+' daripada empat bahagian bilik dipulihkan.')}" width="1000" height="310"></canvas><div class="task-surface">${paused?PausePanel():`<div class="mim-instruction">${T.mim()}<p>${d.instruction}</p><div>${B(I('sound')+' Dengar soalan','speak-question','audio-btn')}${B(I('sound')+' Dengar pilihan','speak-options','audio-btn')}</div></div><h2 id="question-title">${E(q.prompt)}</h2>${q.door===2?`<div class="base-word">Kata dasar: <b>${q.base}</b>${feedback?.correct?`<span class="word-reveal">${q.drop} digugurkan → <b>${q.components[0].correct}</b></span>`:''}</div>`:''}${Components(q,r)}${(isReview()?reviewHint:r.hints)>0?`<div class="hint-box" role="status">${I('bulb')}<div><b>Petunjuk ${isReview()?reviewHint:r.hints}/3</b><p>${E(q.hints[(isReview()?reviewHint:r.hints)-1])}</p></div></div>`:''}${feedback?Feedback(s,q):`<div class="question-actions">${B(I('bulb')+' Petunjuk','hint','hint-btn',(isReview()?reviewHint:r.hints)>=3?'disabled':'')}${B(q.door===2?'Uji mesin · Semak jawapan':'Semak jawapan '+I('check'),'check','primary')}</div>`}<p class="motor-note">${I('hand')} ${q.door===1?'Pilih satu perkataan.':'Seret kad ke ruang, atau pilih kad kemudian ruang.'} ${B('Bantuan kawalan','motor-help','text-btn')}</p>`}</div></section>`;}
  function Components(q,r){return `<div class="components ${q.components.length===3?'three-components':''}">${q.components.map(c=>{const choices=T.choicesFor(q,c,S(),db.settings.guided||r.attempts.filter(a=>!a.correct).length>=3);return `<section class="component ${feedback?.incorrectComponents?.includes(c.id)?'needs-review':''}"><div class="component-heading"><span>${c.label}</span>${q.door===6&&c.id!=='reason'?`<b>${c.id==='first'?'1':'2'}</b>`:''}</div><button class="answer-slot ${answer[c.id]?'filled':''}" data-slot="${c.id}" data-comp="${c.id}" ${feedback?'disabled':''} aria-label="${c.label}: ${E(answer[c.id]||'ruang kosong')}. Pilih kad kemudian ruang ini."><span>${answer[c.id]?E(answer[c.id]):'Letakkan kad di sini'}</span>${answer[c.id]?I('check'):I('puzzle')}</button><div class="choice-cards" role="group" aria-label="Pilihan ${c.label}">${choices.map(value=>{const index=c.choices.indexOf(value),chosen=selected?.component===c.id&&selected.index===index;return `<button class="game-card ${chosen?'selected':''} ${answer[c.id]===value?'placed':''}" data-card data-comp="${c.id}" data-choice="${index}" aria-pressed="${chosen}" ${feedback?'disabled':''}>${c.id==='reason'?I('bulb'):I('puzzle')}<span>${E(value)}</span></button>`;}).join('')}</div></section>`;}).join('')}</div>`;}
  function Feedback(s,q){const z=T.stats(s),d=T.stats(s,q.door);return `<section class="feedback ${feedback.correct?'correct':'retry'}" role="status"><div class="feedback-heading">${I(feedback.correct?'star':'refresh')}<div><h3>${feedback.correct?'Hebat! Misi kecil berjaya.':'Cuba lagi bersama MIM.'}</h3><p>${feedback.correct?E(q.explanation):'Semak bahagian bertanda. '+E(q.hints[Math.max(0,(isReview()?reviewHint:s.records[q.id].hints)-1)])}</p></div></div>${feedback.correct?B(I('sound')+' Dengar penjelasan','speak-explanation','audio-btn'):''}<div class="feedback-status"><span>${E(s.studentName)} · ${E(s.studentClass)}</span><span>Peringkat ${q.door}/6 — ${T.doors[q.door-1].title}</span><span>Cabaran selesai: ${d.completed}/4 · Jumlah: ${z.completed}/24</span><span>Masa peringkat: ${T.formatTime(d.duration)} · Masa menjawab: ${T.formatTime(z.duration)}</span></div><div class="center-actions">${feedback.correct?B(isReview()?'Cabaran semakan seterusnya':q.id%4===0?'Ambil kunci '+I('key'):'Cabaran seterusnya '+I('arrow'),'next','primary'):B('Ubah jawapan dan cuba semula','retry','primary')}${feedback.correct?'':B('Petunjuk seterusnya','hint','secondary',(isReview()?reviewHint:s.records[q.id].hints)>=3?'disabled':'')}${B('Lihat adegan tanpa animasi','calm-now','text-btn')}</div></section>`;}
  function PausePanel(){return `<div class="pause-panel">${I('pause')}<h2>Misi dihentikan seketika.</h2><p id="pause-message">${mode==='hand'&&!tracker.detected?'Tunjukkan tangan semula atau tukar kepada tetikus.':'Berehat dahulu. Masa menjawab berhenti.'}</p><div class="center-actions">${B('Sambung '+I('play'),'unpause','primary','data-requires-hand '+(mode==='hand'&&(!tracker.ready||!tracker.detected)?'disabled':''))}${B('Tukar kawalan','change-control','secondary')}${B('Ringkasan kemajuan','summary','secondary')}${B('Tetapan','settings','secondary')}</div></div>`;}
  function Level(){const s=S(),d=T.doors[Q().door-1],z=T.stats(s,d.id);return `<section class="completion-card"><span class="eyebrow">${practiceSession?'LATIHAN SELESAI':'PERINGKAT SELESAI: '+d.id+'/6'}</span><div class="earned-key" style="--room-color:${d.color}">${I('key')}<b>${d.key}</b></div><h1>${d.title} dipulihkan!</h1><p>${E(s.studentName)} · ${E(s.studentClass)}</p><p>${d.effect}</p><span class="achievement-ribbon">${I('star')} Lencana ${d.badge}</span><div class="completion-stats"><div><b>4/4</b><span>Cabaran selesai</span></div><div><b>${z.score}/4</b><span>Semakan pertama betul</span></div><div><b>${z.hints}</b><span>Petunjuk bahasa</span></div><div><b>${T.formatTime(z.duration)}</b><span>Masa peringkat</span></div></div><p class="muted">Semua usaha dihargai. Kunci dan lencana sama diberikan walaupun menggunakan bantuan.</p><div class="center-actions">${B(practiceSession?'Kembali ke peta':d.id===6?'Ke peti bahasa':'Teruskan pengembaraan',practiceSession?'map':d.id===6?'chest':'next-room','primary')}${B('Lihat ringkasan','summary','secondary')}</div></section>`;}
  function Chest(){return `${Heading('OPERASI ENAM KUNCI AJAIB','Enam kunci. Satu kejayaan!','Letakkan kunci pada huruf yang sama, atau terus pilih Buka peti. Ini ialah perayaan, bukan soalan baharu.')}<section class="chest-scene ${chestOpen?'open':''}"><div class="treasure-chest">${I(chestOpen?'star':'lock')}<h2>${chestOpen?'Tahniah! Kamu telah membantu MIM.':'PETI BAHASA'}</h2><div class="key-slots">${T.doors.map(d=>`<button data-slot="key-${d.id}" data-comp="key-${d.id}" class="key-slot ${chestKeys.includes(d.id)?'filled':''}" ${chestOpen?'disabled':''}>${d.key}<small>${chestKeys.includes(d.id)?'✓':'Ruang '+d.id}</small></button>`).join('')}</div></div><div class="key-cards">${T.doors.map(d=>`<button class="key-card ${chestSelected===d.id?'selected':''}" data-card data-comp="key-${d.id}" data-choice="${d.id}" ${chestKeys.includes(d.id)||chestOpen?'disabled':''}>${I('key')}<b>${d.key}</b><small>Kunci ${d.id}</small></button>`).join('')}</div><div class="center-actions">${B(chestOpen?'Lihat Kad Misi Penjaga Bahasa':'Buka peti '+I('key'),chestOpen?'summary':'open-chest','primary')}</div><p class="muted centered">Pemasa misi sudah berhenti. Aksi ini tidak menambah markah.</p></section>`;}
  function Badges(s){return `<div class="badges">${T.doors.map(d=>{const done=T.stats(s,d.id).completed===4;return `<div class="badge ${done?'earned':''}" style="--room-color:${d.color}"><span>${I(done?'star':'lock')}</span><b>${d.badge}</b><small>${done?'Diperoleh':'Belum diperoleh'}</small></div>`;}).join('')}</div>`;}
  function Results(s){return `<div class="table-scroll"><table><thead><tr><th>Peringkat</th><th>Status</th><th>Masa</th><th>Semakan pertama</th><th>Percubaan semula</th><th>Petunjuk</th></tr></thead><tbody>${T.doors.map(d=>{const z=T.stats(s,d.id),started=z.attempted>0||z.duration>0;return `<tr><th>${d.id}. ${d.title}</th><td>${z.completed===4?'Selesai':started?'Sedang dijawab':'Belum bermula'}</td><td>${z.completed===4?T.formatTime(z.duration):started?'Masa setakat ini: '+T.formatTime(z.duration):'Belum selesai'}</td><td>${z.score}/4</td><td>${z.retries}</td><td>${z.hints}</td></tr>`;}).join('')}</tbody></table></div>`;}
  function Summary(){const s=original();if(!s)return Home();const z=T.stats(s);return `${Heading('RINGKASAN MISI',z.completed===24?'Tahniah, Penjaga Bahasa!':'Setiap langkah ada maknanya.','Rekod ini menerangkan sesi permainan, bukan Tahap Penguasaan PBD.')}<section id="mission-report"><div class="mission-certificate"><div class="certificate-brand">TIBA+ meN- · Misi Selamatkan Bahasa</div><div class="certificate-avatar">${T.avatar(s.avatar)}</div><span class="eyebrow">${z.completed===24?'KAD MISI PENJAGA BAHASA':'KAD KEMAJUAN MISI'}</span><h2>${E(s.studentName)}</h2><p>Kelas ${E(s.studentClass)}</p><h3>${z.completed===24?'Tahniah! Kamu telah membantu MIM.':'Teruskan pengembaraan bersama MIM.'}</h3><p>Peringkat tertinggi selesai: ${z.doors}/6 · Jumlah peringkat selesai: ${z.doors}/6</p>${Badges(s)}<p>${date(s.completedAt||s.startedAt)} · Kad penghargaan usaha dan penyelesaian misi.</p></div><div class="summary-stats"><div><b>${z.completed}/24</b><span>Cabaran selesai</span></div><div><b>${z.score}/24</b><span>Semakan pertama betul</span></div><div><b>${z.independent}/24</b><span>Pertama betul tanpa petunjuk, mod biasa</span></div><div><b>${T.formatTime(z.duration)}</b><span>Jumlah masa menjawab</span></div><div><b>${z.retries}</b><span>Percubaan semula</span></div><div><b>${z.hints}</b><span>Petunjuk bahasa</span></div><div><b>${s.motorHelp}</b><span>Bantuan kawalan</span></div><div><b>${T.controlLabel(s)}</b><span>Kawalan digunakan</span></div></div>${Results(s)}<p class="formative-note">Penyelesaian selepas bantuan tidak bermaksud penguasaan kendiri. Guru menilai kefahaman melalui penerangan murid, item setara dan situasi baharu. Bantuan guru di luar permainan direkodkan berasingan.</p>${z.completed===24?'<div class="follow-up"><h2>Tahniah! Sekarang bina dua ayat menggunakan Papan Ayat meN- bersama guru.</h2><p>Aktiviti maujud dilakukan selepas permainan dan bukan syarat membuka pintu.</p></div>':''}</section><div class="center-actions no-print">${B(I('print')+' Cetak ringkasan','print-summary','primary')}${B('Mulakan murid baharu','new-student','secondary')}${B(z.completed===24?'Peta istana':'Sambung misi','return-mission','secondary')}${B('Bahan maujud untuk dicetak','cards','secondary')}</div><p class="muted centered">Rekod disimpan dalam pelayar ini sahaja. Cetak atau eksport untuk salinan simpanan sebelum memulakan murid baharu.</p>`;}
  function Teacher(){const chosen=db.sessions.find(s=>s.sessionId===teacherId);return `${Heading('RUANG GURU','Lihat perjalanan pembelajaran.','Rekod sesi pada peranti dan pelayar ini sahaja. Tiada penyegerakan atau pengesahan akaun guru.')}<div class="teacher-tools">${B('Panduan PdP','guide','secondary')}${B('Semak semua 24 cabaran','review','primary')}${B('Bahan maujud','cards','secondary')}${B('Mulakan murid baharu','new-student','secondary')}${B('Tutup panel','home','secondary')}</div><p class="local-notice">Panel ini boleh dibuka oleh pengguna peranti yang sama. Tutup selepas digunakan. Rekod versi lama kekal di <a href="legacy/index.html">Misi Enam Pintu Imbuhan</a>.</p><div class="teacher-tools"><label for="record-search">Cari nama atau kelas<input type="search" id="record-search" placeholder="Nama atau kelas"></label><div>${B(I('download')+' Eksport CSV','export','secondary')}${B(I('download')+' CSV percubaan','export-details','secondary')}${B(I('print')+' Cetak laporan','print-teacher','secondary')}${B(I('trash')+' Padam terpilih','delete-gate','danger',!selectedRecords.size?'disabled':'')}</div></div><p class="muted">${selectedRecords.size?selectedRecords.size+' sesi ditandakan untuk eksport / padam.':'Eksport merangkumi semua sesi. Tandakan sesi untuk mengehadkan eksport.'}</p><section id="teacher-report"><h2>Laporan Misi Selamatkan Bahasa</h2>${db.sessions.length?`<div class="table-scroll"><table><thead><tr><th class="no-print">Pilih</th><th>Murid</th><th>Tarikh</th><th>Peringkat</th><th>Semakan pertama</th><th>Tanpa petunjuk, biasa</th><th>Cuba semula</th><th>Petunjuk bahasa</th><th>Bantuan kawalan</th><th>Masa menjawab</th><th class="no-print">Butiran</th></tr></thead><tbody>${[...db.sessions].reverse().map(s=>{const z=T.stats(s);return `<tr class="record-row" data-search="${E((s.studentName+' '+s.studentClass).toLowerCase())}"><td class="no-print"><input type="checkbox" data-record="${E(s.sessionId)}" aria-label="Pilih ${E(s.studentName)}" ${selectedRecords.has(s.sessionId)?'checked':''}></td><th>${E(s.studentName)}<small>${E(s.studentClass)}</small></th><td>${date(s.startedAt)}</td><td>${z.doors}/6</td><td>${z.score}/24</td><td>${z.independent}/24</td><td>${z.retries}</td><td>${z.hints}</td><td>${s.motorHelp}</td><td>${T.formatTime(z.duration)}</td><td class="no-print">${B('Lihat','record','secondary',`data-id="${E(s.sessionId)}"`)}</td></tr>`;}).join('')}</tbody></table></div>`:'<div class="empty-state"><h3>Belum ada rekod misi baharu.</h3><p>Latihan awal dan semakan guru tidak mencipta rekod murid.</p></div>'}${chosen?TeacherDetail(chosen):''}</section>`;}
  function TeacherDetail(s){const z=T.stats(s);return `<section class="record-detail" id="record-detail"><div class="section-top"><h2>${E(s.studentName)} · ${E(s.studentClass)}</h2>${B('Buka sesi / ulang latihan','open-session','secondary no-print',`data-id="${E(s.sessionId)}"`)}</div><p>${z.completed}/24 cabaran selesai · ${T.controlLabel(s)} · ${s.motorHelp} bantuan kawalan · ${s.trackingLosses} kehilangan tracking.</p>${Results(s)}<form id="external-help" class="no-print"><label for="external-help-text">Catatan bantuan guru di luar permainan</label><textarea id="external-help-text" rows="3" maxlength="1500">${E(s.externalHelp)}</textarea><button type="submit" class="btn secondary">Simpan catatan berasingan</button></form><p class="print-only">Bantuan luar: ${E(s.externalHelp)||'Tiada catatan.'}</p><h3>Jejak semakan jawapan</h3>${T.questions.map(q=>{const r=s.records[q.id];return `<details class="question-record"><summary>${q.id}. ${E(q.prompt)}<small>${r.attempts.length} semakan · ${r.hints} petunjuk · ${T.formatTime(r.duration)}</small></summary><p>Jawapan: ${q.components.map(c=>`${c.label}: <b>${E(c.correct)}</b>`).join(' · ')}</p>${r.attempts.length?`<ol>${r.attempts.map(a=>`<li>${q.components.map(c=>`${c.label}: ${E(a.value[c.id])}`).join(' · ')}<br><b>${a.correct?'Betul':'Belum tepat'}</b> · Petunjuk sebelum semakan: ${a.hintsAtCheck} · ${a.guided?'Mod bimbingan':'Mod biasa'} · ${a.mode==='hand'?'Gerakan tangan':'Tetikus'}</li>`).join('')}</ol>`:'<p>Belum disemak.</p>'}</details>`;}).join('')}</section>`;}
  function ReviewNav(){return `<div class="review-nav"><b>Semakan guru · Tiada pemasa atau rekod murid</b><label>Cabaran <select id="review-question">${T.questions.map(q=>`<option value="${q.id}" ${q.id===qId?'selected':''}>${q.id}. ${T.doors[q.door-1].title}</option>`).join('')}</select></label>${B('Lihat skema','review-answer','secondary')}${B('Keluar semakan','end-review','secondary')}</div>`;}
  function Guide(){return `${Heading('PANDUAN GURU','Bahasa, gerakan dan pemikiran.','Gunakan penyesuaian mengikut keperluan murid, bukan andaian terhadap semua murid inklusif.')}<article class="teacher-guide"><div class="teacher-tools">${B('Semak 24 cabaran','review','primary')}${B('Panel rekod','teacher','secondary')}${B('Cetak bahan maujud','cards','secondary')}</div><h2>Tujuan pembelajaran</h2><p>Mengenal pasti kata berawalan meN-, memadankan kata dasar dengan hasil, menggunakan kata dalam konteks, membaiki kesalahan serta memilih tindakan, urutan dan alasan. Pembinaan dua ayat sendiri diteruskan melalui bahan maujud.</p><p><b>Penjajaran berdasarkan brief:</b> DSKP Bahasa Melayu SK Tahun 2, SK 5.2 dan SP 5.2.1(iii). Peringkat permainan bukan Tahap Penguasaan PBD. Sistem tidak menetapkan TP.</p><h2>Cadangan sesi 60 minit</h2><div class="table-scroll"><table><thead><tr><th>Aktiviti</th><th>Masa</th><th>Bentuk</th></tr></thead><tbody><tr><td>Imbas & Kenal</td><td>7 minit</td><td>Digital</td></tr><tr><td>Detektif Imbuhan</td><td>5 minit</td><td>Digital</td></tr><tr><td>Escape room</td><td>30 minit</td><td>Digital</td></tr><tr><td>Manipulasi awalan, kata dasar dan cip huruf</td><td>6 minit</td><td>Maujud</td></tr><tr><td>Bina dua ayat sendiri</td><td>12 minit</td><td>Maujud</td></tr></tbody></table></div><p><b>42 minit digital (70%) + 18 minit maujud (30%).</b> Ini cadangan PdP, bukan had masa permainan. Bahagikan kepada beberapa sesi dan catat masa sebenar jika perlu.</p><h2>Persediaan dan kawalan</h2><ol><li>Mulakan dengan membaca dan melukis dalam Imbas & Kenal. Kemudian perkenalkan perubahan t, s, k dan p pada contoh bank.</li><li>Bantu murid mengisi nama dan kelas. Pilih avatar hiasan.</li><li>Pilih tetikus atau gerakan tangan. Tetikus tidak memerlukan kamera atau model.</li><li>Untuk tangan, tekan Aktifkan kamera. Benarkan akses dalam pelayar HTTPS atau localhost. Gunakan satu tangan, pencahayaan sekata dan jarak yang selesa.</li><li>Jari telunjuk menggerakkan penunjuk. Cubit untuk memegang, gerakkan, kemudian buka cubitan untuk melepaskan. Buka cubitan dahulu selepas tangan dikesan semula.</li><li>Jika cubitan sukar, pilih Tahan untuk pilih. Tempoh lalai 1.2 saat, boleh dilaras 0.6–3 saat. Pilih kad, kemudian ruang. Keluar dari sasaran membatalkan gelang.</li><li>Kalibrasi kawasan gerakan dan pilih tangan kiri, kanan atau mana-mana. Gunakan tiga sasaran latihan. Saiz sasaran kekal besar dalam semua bilik.</li><li>Semua jawapan direkodkan hanya selepas semakan lengkap. Salah lepas, tracking hilang atau jawapan separa bukan kesalahan bahasa.</li></ol><h2>Sokongan inklusif</h2><p>Mod bimbingan menyediakan dua pilihan setiap komponen, termasuk sebab dan kedua-dua langkah urutan. Tetapan teks besar, kontras tinggi, paparan tenang, kurangkan hiasan, audio dan pratonton kamera boleh disesuaikan. Sokongan kamera bukan syarat kejayaan. Nama dan kelas boleh ditaip dengan bantuan guru.</p><h2>Aras pemikiran</h2><div class="table-scroll"><table><thead><tr><th>Bilik</th><th>Aras dan tugasan</th></tr></thead><tbody>${T.doors.map(d=>`<tr><th>${d.id}. ${d.title}</th><td>${d.level}. ${d.instruction}</td></tr>`).join('')}</tbody></table></div><p>Peringkat 1–3 membina asas dan aplikasi; 4–6 melibatkan KBAT dengan bimbingan. Aras mencipta diteruskan melalui ayat maujud.</p><h2>Pentaksiran yang bermakna</h2><p>Gunakan item setara sebelum dan selepas aktiviti: contohnya mengenal membaca sebelum sesi dan mengenal membawa selepas sesi. Gunakan satu situasi baharu untuk melihat pemindahan pembelajaran. Minta murid menerangkan alasan menggunakan kata sendiri.</p><p>Semakan pertama betul direkodkan berasingan daripada semakan pertama betul tanpa petunjuk dalam mod biasa. Penggunaan bimbingan, setiap petunjuk dan percubaan direkodkan. Penyelesaian semua bilik selepas bantuan bukan bukti penguasaan kendiri. Catat bantuan guru di luar permainan pada ruang berasingan dalam panel rekod.</p><h2>Aktiviti maujud: bina dua ayat</h2><p>Cetak kad dan papan. Lekatkan pada kadbod dan gunakan Velcro atau magnet yang sesuai. Manipulasi awalan, kata dasar dan cip huruf; tunjuk hasil sebenar daripada bank, bukan cantuman teks yang menghasilkan mentulis.</p><blockquote>Kelas akan menerima tetamu. Lantai berdebu dan papan pameran kosong. Bina dua ayat tentang tindakan yang membantu.</blockquote><p>Contoh guru: “Saya menyapu lantai.” dan “Saya melukis bunga untuk papan pameran.” Terima ayat lain yang tepat, bermakna dan sesuai. Nilai bentuk meN-, makna ayat dan kesesuaian tindakan. Murid boleh menyusun kad, membaca, menunjuk atau menjawab secara lisan.</p><h2>Masa dan rekod</h2><p>Masa menjawab merangkumi soalan aktif, cubaan semula dan membaca petunjuk. Persediaan, latihan awal, latihan kawalan, jeda, peralihan, maklum balas ganjaran dan pembukaan peti tidak dikira. Masa tidak menentukan markah atau ganjaran.</p><p>Rekod disimpan secara setempat pada peranti dan pelayar ini. Ia tidak kekal jika data pelayar dipadam. Cetak ringkasan atau eksport CSV untuk salinan simpanan sebelum memulakan murid baharu. Sesi baharu tidak menindih sesi lama. Semakan guru dan latihan ulangan tidak mengubah rekod asal.</p><h2>Privasi dan batas perkakasan</h2><p>Video diproses pada peranti melalui MediaPipe Hand Landmarker. Tiada rakaman atau muat naik video. Matikan kamera apabila selesai. Murid baharu menghentikan semua trek kamera. Jika kamera, izin atau model gagal, teruskan dengan tetikus. Suara Bahasa Melayu bergantung pada peranti.</p><p>Untuk penggunaan luar talian, gunakan pakej lengkap yang merangkumi model dan WASM melalui localhost. Membuka satu fail HTML sahaja tidak menjamin tracking luar talian.</p><p class="source-links">Rujukan teknikal: <a href="https://developers.google.com/edge/mediapipe/solutions/vision/hand_landmarker/web_js" target="_blank" rel="noopener">Google AI Edge Hand Landmarker</a> · <a href="https://developer.mozilla.org/en-US/docs/Web/API/MediaDevices/getUserMedia" target="_blank" rel="noopener">MDN getUserMedia</a>.</p></article>`;}
  function PrintCards(){const groups=[['Kad awalan',['me-','mem-','men-','meng-','meny-','menge-']],['Kad kata dasar',T.words.map(w=>w.base)],['Kad kata berimbuhan',T.words.map(w=>w.result)],['Cip huruf',['p','t','k','s','p','t','k','s']],['Kad pelaku',['Saya','Ali','Siti','Amin','Lina','MIM','Kami','Ibu']],['Kad objek / keterangan',['lantai','buku cerita','dinding','gambar bunga','kertas','pesanan','di kelas','untuk papan pameran']],['Kad situasi',['Kelas akan menerima tetamu. Lantai berdebu dan papan pameran kosong.','MIM belum membaca arahan. Dia perlu melukis gambar mengikut kad.','Ibu memerlukan nota tarikh Hari Sukan. Kertas dan pensel tersedia.']],['Kad kosong',['','','','','','']]];return `${Heading('BAHAN MAUJUD','Papan Ayat meN-','Cetak, gunting dan lekatkan pada kadbod. Gunakan Velcro atau magnet mengikut kesesuaian.')}<div class="center-actions no-print">${B(I('print')+' Cetak semua bahan','print-cards','primary')}${B('Panduan guru','guide','secondary')}</div><div id="print-materials">${groups.map(([name,items])=>`<section class="materials-group"><h2>${name}</h2><div class="print-card-grid">${items.map(s=>`<div class="print-card ${s.length>60?'situation-card':''}">${E(s)||'<span>Idea baharu</span>'}</div>`).join('')}</div></section>`).join('')}<section class="materials-group"><h2>Papan bina kata</h2><div class="physical-board"><div>Awalan</div><div>Kata dasar</div><div>Hasil</div></div><p>Contoh t, s, k dan p digugurkan hanya bagi kata lazim yang dipelajari. Semak hasil penuh pada kad berimbuhan.</p></section><section class="materials-group"><h2>Papan ayat · Ayat 1</h2><div class="physical-board"><div>Siapa</div><div>Perbuatan</div><div>Objek / keterangan</div></div><h2>Papan ayat · Ayat 2</h2><div class="physical-board"><div>Siapa</div><div>Perbuatan</div><div>Objek / keterangan</div></div></section><section class="materials-group"><h2>Panduan pemerhatian guru</h2><p>Terima ayat yang menggunakan meN- dengan tepat, mempunyai makna jelas dan sesuai dengan situasi. Minta murid menerangkan pilihan mereka. Aktiviti ini bukan syarat membuka pintu digital.</p><p>Nama: _____________________ Kelas: __________ Tarikh: __________</p><div class="physical-board"><div>Ketepatan kata meN-<br>________________</div><div>Makna ayat<br>________________</div><div>Kesesuaian tindakan<br>________________</div></div><p>Bantuan guru: ____________________________________________________</p></section></div>`;}
  function openModal(type){flush();lastTime=null;hub.cancel();hub.dwell.reset();returnFocus=document.activeElement;modal=type;renderModal();$('#modal-root button')?.focus();}
  function closeModal(){const refresh=modal==='settings';modal=null;$('#app').inert=false;$('#modal-root').innerHTML='';document.body.classList.remove('modal-open');hub.cancel();if(refresh)render();if(returnFocus?.isConnected)returnFocus.focus();else $('#main')?.focus();lastTime=canTime()?performance.now():null;}
  function renderModal(){const root=$('#modal-root');$('#app').inert=!!modal;if(!modal){root.innerHTML='';document.body.classList.remove('modal-open');return;}document.body.classList.add('modal-open');let title='',body='';
    if(modal==='settings'){title='Belajar dengan selesa';body=`<p>Semua pilihan mengekalkan 6 bilik dan 24 cabaran.</p><div class="setting-list">${[['largeText','Teks besar'],['contrast','Kontras tinggi'],['calm','Paparan tenang · matikan animasi'],['simple','Kurangkan hiasan'],['mute','Matikan bunyi'],['guided','Mod bimbingan · dua pilihan setiap komponen'],['preview','Tunjukkan pratonton kamera']].map(([key,label])=>`<label class="setting"><span>${label}</span><input type="checkbox" role="switch" data-setting="${key}" ${db.settings[key]?'checked':''}></label>`).join('')}</div><p class="muted">Mod bimbingan tetap memerlukan alasan dan urutan. Pilihan betul disusun semula, bukan sentiasa di tempat yang sama.</p>${B('Selesai','settings-done','primary full')}`;}
    if(modal==='teacher'){title='Ruang guru';body=`<p>Panduan dan semakan guru tersedia tanpa mengubah rekod murid. Panel rekod pula memaparkan nama dan pencapaian pada peranti ini.</p><div class="modal-actions">${B('Panduan penggunaan guru','guide','primary')}${B('Semak semua 24 cabaran','review','secondary')}${B('Buka panel rekod murid','teacher','secondary')}${B('Bahan maujud untuk dicetak','cards','secondary')}</div><p class="muted">Panel ini tidak mempunyai pengesahan identiti akaun.</p>`;}
    if(modal==='motor'){title='Kawalan yang mudah';body=`<div class="control-demo">${I('hand')} ${I('arrow')} ${I('puzzle')}</div><ol><li>Gerakkan tetikus atau jari telunjuk ke kad.</li><li>Klik kad, atau cubit dan buka. Dalam mod tahan, tunggu gelang penuh.</li><li>Pilih ruang sasaran. Kamu juga boleh memegang, menyeret dan melepaskan kad.</li><li>Selepas semua ruang diisi, pilih Semak jawapan.</li></ol><p>Kad yang tersasar dikembalikan. Ia tidak dikira sebagai jawapan salah.</p>${B('Saya faham','close-modal','primary full')}`;}
    if(modal==='delete'){title='Padam rekod terpilih?';body=`<p>${selectedRecords.size} sesi akan dipadam daripada pelayar ini. Eksport CSV dahulu jika diperlukan. Tindakan ini tidak boleh dibatalkan.</p><div class="center-actions">${B('Kekalkan rekod','close-modal','secondary')}${B('Ya, padam','delete-confirm','danger')}</div>`;}
    if(modal==='scheme'){title='Skema semakan guru';body=`<p>${Q().components.map(c=>`<b>${c.label}:</b> ${E(c.correct)}`).join('<br>')}</p><p>${E(Q().explanation)}</p>${B('Tutup skema','close-modal','primary')}`;}
    root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="section-top"><h2 id="modal-title">${title}</h2>${B(I('close'),'close-modal','icon-btn','aria-label="Tutup dialog"')}</div>${body}</section></div>`;
  }
  function pickCard(component,index){if(view==='training'){training.selected=true;render();return;}if(view==='chest'){chestSelected=index;render();return;}if(view!=='question'||feedback||S().pausedState)return;const c=Q().components.find(c=>c.id===component);if(!c||!c.choices[index])return;flush();selected={component,index};if(Q().door===1){answer[component]=c.choices[index];selected=null;}render();$(`[data-card][data-comp="${component}"][data-choice="${index}"]`)?.focus({preventScroll:true});}
  function place(component){if(view==='training'){if(training.selected){training.placed=true;training.step=3;selected=null;render();}else toast('Pilih kad bintang dahulu.');return;}if(view==='chest'){const id=Number(component.split('-')[1]);if(chestSelected===id){if(!chestKeys.includes(id))chestKeys.push(id);chestSelected=null;render();}else toast('Pilih kunci yang sepadan dengan huruf dan nombor ruang.');return;}if(view!=='question'||feedback||S().pausedState)return;if(!selected||selected.component!==component){toast('Pilih kad untuk ruang ini dahulu.');return;}flush();const c=Q().components.find(c=>c.id===component);answer[component]=c.choices[selected.index];selected=null;render();$(`[data-slot="${component}"]`)?.focus({preventScroll:true});}
  function drop(card,target,source='mouse'){noteInput(source);if(card.component!==target.dataset.comp){toast('Kad kembali ke tempat asal. Gunakan ruang dengan label yang sama.');return;}if(view==='training'){training.selected=true;place('training');return;}if(view==='chest'){chestSelected=card.index;place(card.component);return;}if(view==='question'&&!feedback&&!S().pausedState){selected={component:card.component,index:card.index};place(card.component);}}
  function trainingMove(x,y){if(view!=='training'||training.step!==0)return;const el=document.elementFromPoint(x,y)?.closest('[data-training-target]');if(el)trainTarget(Number(el.dataset.trainingTarget));}
  function trainTarget(index){if(training.step!==0||training.targets.includes(index))return;training.targets.push(index);const el=$(`[data-training-target="${index}"]`);if(el){el.classList.add('reached');el.innerHTML=I('check');}if(training.targets.length===3){training.step=1;setTimeout(()=>{if(view==='training')render();},150);}}
  function enterRoom(id){const s=original();if(!s||!T.isUnlocked(s,id))return;flush();lastTime=null;practiceSession=null;reviewSession=null;if(T.stats(s,id).completed===4){practiceSession=T.newSession(s.studentName,s.studentClass,s.avatar);for(const q of T.questions.filter(q=>q.door<id))practiceSession.records[q.id].completed=true;}qId=T.questions.find(q=>q.door===id&&!S().records[q.id].completed).id;answer={};feedback=null;go('intro');}
  function startQuestion(){if(mode==='hand'&&(!tracker.ready||!tracker.detected)){controlReturn='question';go('controls');toast('Aktifkan kamera dan tunjukkan tangan, atau pilih tetikus.');return;}answer={};selected=null;feedback=null;S().pausedState=false;if(!isReview())T.recordControl(S(),mode);save();go('question');}
  function check(){if(view!=='question'||feedback||S().pausedState)return;if(!T.completeAnswer(Q(),answer)){toast('Lengkapkan semua ruang dahulu. Belum ada jawapan dikira salah.');return;}clearTimeout(toastTimer);$('#notice').hidden=true;flush();lastTime=null;let result;if(isReview()){result={accepted:true,correct:T.isCorrect(Q(),answer),incorrectComponents:Q().components.filter(c=>answer[c.id]!==c.correct).map(c=>c.id)};if(result.correct)S().records[qId].completed=true;}else result=T.submit(S(),qId,answer,{mode:lastInputMode,guided:db.settings.guided||S().records[qId].attempts.filter(a=>!a.correct).length>=3});if(!result.accepted)return;feedback=result;S().pausedState=false;if(!result.correct){if(isReview())reviewHint=Math.min(3,reviewHint+1);else T.addHint(S(),qId);}if(result.correct)sound('success');save();render();$('.feedback')?.scrollIntoView({block:'nearest',behavior:db.settings.calm?'instant':'smooth'});$('.feedback button')?.focus({preventScroll:true});}
  function hint(){if(view!=='question'||S().pausedState)return;flush();if(isReview())reviewHint=Math.min(3,reviewHint+1);else T.addHint(S(),qId);save();render();toast(Q().hints[(isReview()?reviewHint:S().records[qId].hints)-1]);}
  function pause(message='Masa menjawab dihentikan seketika.'){if(view!=='question'||!S())return;flush();lastTime=null;S().pausedState=true;hub.hide();stopSpeech();save();render();if(message)toast(message);}
  function canTime(){return view==='question'&&S()&&!isReview()&&!S().pausedState&&!feedback?.correct&&!modal&&!document.hidden&&!(mode==='hand'&&trackingHold);}
  function flush(){if(lastTime!==null&&S()){const now=performance.now();T.addTime(S(),qId,now-lastTime);lastTime=now;save();}}
  function updateClock(){if(!S())return;all('[data-time="total"]').forEach(el=>el.textContent=T.formatTime(S().totalActiveDuration));}
  function updateTracking(){if(typeof tracker==='undefined')return;all('[data-tracking-status]').forEach(el=>el.textContent=mode==='hand'?(tracker.message||'Kamera dimatikan'):'');const ready=mode==='mouse'||tracker.ready&&tracker.detected;all('#training-start,[data-requires-hand]').forEach(el=>el.disabled=!ready);tracker.showPreview(db.settings.preview&&mode==='hand');$('#hand-dock').hidden=mode!=='hand';$('#hand-dock-status').textContent=tracker.message||'Kamera dimatikan';}
  function stopSpeech(){window.speechSynthesis?.cancel();}
  function speak(text){stopSpeech();if(db.settings.mute){toast('Bunyi dimatikan dalam Tetapan.');return;}const voices=window.speechSynthesis?.getVoices()||[],voice=voices.find(v=>/^ms[-_]MY$/i.test(v.lang))||voices.find(v=>/^ms(?:[-_]|$)/i.test(v.lang));if(!voice){toast('Suara Bahasa Melayu tidak tersedia. Baca arahan bertulis atau minta guru membacakannya.');return;}const u=new SpeechSynthesisUtterance(text);u.voice=voice;u.lang=voice.lang;u.rate=.85;u.onerror=()=>toast('Audio tidak tersedia. Arahan bertulis kekal boleh dibaca.');speechSynthesis.speak(u);}
  function sound(kind){if(db.settings.mute)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=new C(),notes=kind==='success'?[523,659,784]:[440];notes.forEach((f,i)=>{const o=c.createOscillator(),g=c.createGain();o.frequency.value=f;g.gain.setValueAtTime(.025,c.currentTime+i*.12);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+i*.12+.22);o.connect(g);g.connect(c.destination);o.start(c.currentTime+i*.12);o.stop(c.currentTime+i*.12+.25);});setTimeout(()=>c.close(),800);}catch{}}
  function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function print(kind){flush();lastTime=null;document.body.dataset.print=kind;window.print();}
  let lastInputMode='mouse';
  function noteInput(source){lastInputMode=source==='hand'?'hand':'mouse';if(view==='question'&&S()&&!S().pausedState&&!isReview()){T.recordControl(S(),lastInputMode);save();}}
  function activate(el,source='mouse'){noteInput(source);if(el.hasAttribute('data-card')){pickCard(el.dataset.comp,Number(el.dataset.choice));return;}if(el.hasAttribute('data-slot')){place(el.dataset.comp);return;}const a=el.dataset.action;
    if(['guide','teacher','cards','review'].includes(a)&&modal)closeModal();
    switch(a){
      case'home':flush();lastTime=null;mode='mouse';tracker.stop();practiceSession=null;reviewSession=null;feedback=null;go('home');break;
      case'new-student':flush();lastTime=null;mode='mouse';tracker.stop();practiceSession=null;reviewSession=null;feedback=null;go('register');break;
      case'scan':scanIndex=0;go('scan');break;case'scan-prev':scanIndex=(scanIndex+T.words.length-1)%T.words.length;render();break;case'scan-next':scanIndex=(scanIndex+1)%T.words.length;render();break;case'scan-word':scanIndex=Number(el.dataset.index);render();break;case'speak-scan':speak(T.words[scanIndex].base+' menjadi '+T.words[scanIndex].result);break;
      case'detective':detectiveIndex=0;detectiveFeedback='';go('detective');break;case'detect-answer':{const q=T.detective[detectiveIndex];detectiveFeedback=(Number(el.dataset.index)===q.answer?'Hebat! ':'Cuba lagi. ')+q.explanation;render();break;}case'detect-repeat':detectiveFeedback='';render();break;case'detect-next':detectiveIndex=(detectiveIndex+1)%4;detectiveFeedback='';render();break;
      case'resume':if(original()){controlReturn='map';go('controls');}break;
      case'controls':controlReturn='map';go('controls');break;case'change-control':controlReturn='question';go('controls');break;case'control-back':go(controlReturn==='question'?'question':original()?'map':'home');break;
      case'mode-mouse':mode='mouse';tracker.stop();trackingHold=false;render();break;
      case'mode-hand':mode='hand';trackingHold=!tracker.detected;render();break;
      case'camera-on':if(mode==='hand'&&tracker.state!=='loading')tracker.start();break;
      case'camera-off':tracker.stop();if(view==='question')pause('Kamera dimatikan. Pilih tetikus atau aktifkan semula kamera.');break;
      case'camera-preview':db.settings.preview=!db.settings.preview;save();settings();break;
      case'train':if(mode==='hand'&&(!tracker.ready||!tracker.detected))return;training={step:0,targets:[],selected:false,placed:false};go('training');break;
      case'train-target':trainTarget(Number(el.dataset.index));break;case'train-select':training.step=2;render();break;case'train-repeat':training={step:0,targets:[],selected:false,placed:false};render();break;
      case'training-done':if(training.step!==3)return;if(controlReturn==='question'){S().pausedState=true;go('question');}else go('map');break;
      case'enter-room':enterRoom(Number(el.dataset.door));break;
      case'continue':if(T.stats(original()).completed===24){chestKeys=[];chestOpen=false;go('chest');}else enterRoom(T.currentUnsolved(original()).door);break;
      case'start-room':startQuestion();break;
      case'map':flush();lastTime=null;practiceSession=null;reviewSession=null;feedback=null;if(original()){original().pausedState=true;save();go('map');}else go('home');break;
      case'check':check();break;case'hint':hint();break;case'retry':feedback=null;render();$('.game-card')?.focus();break;
      case'next':if(!feedback?.correct)return;if(isReview()){qId=qId===24?1:qId+1;reviewHint=0;startQuestion();}else if(qId%4===0){sound('success');go('level');}else{qId++;startQuestion();}break;
      case'next-room':enterRoom(Q().door+1);break;
      case'pause':pause();break;case'unpause':if(mode==='hand'&&(!tracker.ready||!tracker.detected))return;S().pausedState=false;trackingHold=false;if(!isReview())T.recordControl(S(),mode);save();render();break;
      case'summary':flush();lastTime=null;if(S())S().pausedState=true;save();practiceSession=null;reviewSession=null;feedback=null;go('summary');break;
      case'return-mission':if(original()?.completionStatus==='complete')go('map');else if(S()&&T.currentUnsolved(S())){qId=T.currentUnsolved(S()).id;answer={};feedback=null;S().pausedState=true;go('question');}break;
      case'chest':practiceSession=null;chestKeys=[];chestSelected=null;chestOpen=false;go('chest');break;case'open-chest':chestKeys=[1,2,3,4,5,6];chestOpen=true;sound('success');render();break;
      case'calm-now':db.settings.calm=true;save();settings();toast('Paparan tenang diaktifkan. Teruskan apabila bersedia.');break;
      case'motor-help':if(view==='question'&&!isReview()&&!practiceSession){S().motorHelp++;save();}openModal('motor');break;
      case'teacher-gate':openModal('teacher');break;case'settings':openModal('settings');break;case'close-modal':closeModal();break;case'settings-done':closeModal();break;
      case'guide':go('guide');break;case'cards':go('cards');break;
      case'teacher':flush();lastTime=null;mode='mouse';tracker.stop();practiceSession=null;reviewSession=null;selectedRecords.clear();teacherId=null;go('teacher');break;
      case'record':teacherId=el.dataset.id;render();$('#record-detail')?.scrollIntoView({block:'start'});break;
      case'open-session':db.activeId=el.dataset.id;save();controlReturn='map';go('controls');break;
      case'review':flush();lastTime=null;mode='mouse';tracker.stop();practiceSession=null;reviewSession=T.newSession('Semakan guru','Tiada rekod murid');qId=1;reviewHint=0;startQuestion();break;
      case'end-review':reviewSession=null;feedback=null;go('guide');break;case'review-answer':openModal('scheme');break;
      case'export':download(T.toCSV(selectedRecords.size?db.sessions.filter(s=>selectedRecords.has(s.sessionId)):db.sessions),'tiba-men-misi-rekod.csv');break;
      case'export-details':download(T.detailCSV(selectedRecords.size?db.sessions.filter(s=>selectedRecords.has(s.sessionId)):db.sessions),'tiba-men-misi-percubaan.csv');break;
      case'delete-gate':if(selectedRecords.size)openModal('delete');break;case'delete-confirm':db.sessions=db.sessions.filter(s=>!selectedRecords.has(s.sessionId));if(selectedRecords.has(db.activeId))db.activeId=null;if(selectedRecords.has(teacherId))teacherId=null;selectedRecords.clear();save();closeModal();render();break;
      case'print-summary':print('summary');break;case'print-teacher':print('teacher');break;case'print-cards':print('cards');break;
      case'speak-question':speak(T.doors[Q().door-1].instruction+' '+Q().prompt);break;case'speak-options':speak(Q().components.map(c=>c.label+': '+T.choicesFor(Q(),c,S(),db.settings.guided||S().records[qId].attempts.filter(a=>!a.correct).length>=3).join('. ')).join('. '));break;case'speak-explanation':speak(Q().explanation);break;
      case'fullscreen':if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>toast('Skrin penuh tidak tersedia dalam paparan ini. Buka laman dalam tab pelayar.'));break;
      case'scroll-up':window.scrollBy({top:-innerHeight*.55,behavior:db.settings.calm?'instant':'smooth'});hub.dwell.reset();break;case'scroll-down':window.scrollBy({top:innerHeight*.55,behavior:db.settings.calm?'instant':'smooth'});hub.dwell.reset();break;
    }
  }
  document.addEventListener('submit',e=>{if(e.target.id==='registration'){e.preventDefault();const f=e.target,name=f.elements.studentName.value.trim(),cls=f.elements.studentClass.value.trim();if(!name||!cls){$('#form-error').textContent='Sila isi nama dan kelas dahulu.';(!name?f.elements.studentName:f.elements.studentClass).focus();return;}const s=T.newSession(name,cls,f.elements.avatar.value);db.sessions.push(s);db.activeId=s.sessionId;save();controlReturn='map';go('controls');}else if(e.target.id==='external-help'){e.preventDefault();const s=db.sessions.find(s=>s.sessionId===teacherId);if(s){s.externalHelp=$('#external-help-text').value.trim().slice(0,1500);save();toast('Catatan bantuan luar disimpan secara berasingan.');}}});
  document.addEventListener('change',e=>{const el=e.target;if(el.dataset.setting){flush();db.settings[el.dataset.setting]=el.checked;if(el.dataset.setting==='mute')stopSpeech();save();settings();}if(el.id==='activation-setting'){db.settings.activation=el.value;hub.cancel();hub.dwell.reset();save();}if(el.id==='hand-setting'){db.settings.hand=el.value;tracker.filter.reset();save();}if(el.id==='dwell-setting'){db.settings.dwellMs=Math.max(600,Math.min(3000,Number(el.value)*1000||1200));el.value=db.settings.dwellMs/1000;save();}if(el.id==='range-setting'){db.settings.range=Number(el.value)/100;tracker.filter.reset();$('#range-label').textContent=el.value+'%';save();}if(el.dataset.record){if(el.checked)selectedRecords.add(el.dataset.record);else selectedRecords.delete(el.dataset.record);render();}if(el.id==='review-question'){qId=Number(el.value);reviewHint=0;startQuestion();}});
  document.addEventListener('input',e=>{if(e.target.id==='record-search'){const query=e.target.value.trim().toLowerCase();all('.record-row').forEach(row=>row.hidden=!row.dataset.search.includes(query));}});
  document.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const els=all('#modal-root button:not(:disabled),#modal-root input,#modal-root select'),first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
  setInterval(()=>{if(canTime()){if(lastTime===null)lastTime=performance.now();else flush();updateClock();}else lastTime=null;},400);
  const autoPause=()=>{if(view==='question'&&S()&&!S().pausedState&&!feedback?.correct)pause('Misi dijeda apabila halaman tidak aktif. Pilih Sambung apabila bersedia.');};
  window.addEventListener('blur',autoPause);document.addEventListener('visibilitychange',()=>{if(document.hidden){autoPause();hub.hide();}});
  window.addEventListener('pagehide',()=>{flush();lastTime=null;mode='mouse';tracker.stop();if(original())original().pausedState=true;save();});
  window.addEventListener('afterprint',()=>delete document.body.dataset.print);
  window.addEventListener('storage',e=>{if(e.key!==T.STORAGE_KEY)return;lastTime=null;mode='mouse';tracker.stop();try{db=T.readDatabase(e.newValue);practiceSession=null;reviewSession=null;modal=null;view='home';render();toast('Rekod dikemas kini oleh tab lain. Sambung dari menu utama.');}catch{storageOK=false;toast('Rekod tab lain tidak dapat dibaca. Data tidak ditindih.');}});
  render();
})(window.Tiba);
